fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Since a and b are guaranteed to have the same length and b contains no zeros,
    // we can safely zip and compute element-wise remainder.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x % y)
     .collect()
}

fn main() {
    // Example usage
    let a = vec![10, 20, -7, 0];
    let b = vec![3, 6, 5, 1];
    let result = element_wise_modulo(a, b);
    println!("{:?}", result);  // [1, 2, -2, 0]
}